# Let's implement graph utilities from scratch
from collections import defaultdict, deque

edges = [(0, 1), (0, 12), (0, 23), (1, 2), (1, 8), (2, 3), (2, 19), (3, 4), (3, 15), 
         (4, 5), (4, 11), (5, 6), (5, 22), (6, 7), (6, 18), (7, 8), (7, 14), (8, 9), 
         (9, 10), (9, 21), (10, 11), (10, 17), (11, 12), (12, 13), (13, 14), (13, 20), 
         (14, 15), (15, 16), (16, 17), (16, 23), (17, 18), (18, 19), (19, 20), (20, 21), 
         (21, 22), (22, 23)]

n = 24
adj = defaultdict(set)
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check girth using BFS from each vertex
def find_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

girth = find_girth(adj, n)
print(f"Girth: {girth}")
print(f"Number of edges: {len(edges)}")

# Check 3-colorability
def is_k_colorable(adj, n, k):
    nodes = list(range(n))
    colors = {}

    def backtrack(idx):
        if idx == len(nodes):
            return True
        node = nodes[idx]
        neighbor_colors = {colors[nb] for nb in adj[node] if nb in colors}
        for c in range(k):
            if c not in neighbor_colors:
                colors[node] = c
                if backtrack(idx + 1):
                    return True
                del colors[node]
        return False

    if backtrack(0):
        return True, colors
    return False, None

result, coloring = is_k_colorable(adj, n, 3)
print(f"Is 3-colorable: {result}")
if result:
    valid = all(coloring[u] != coloring[v] for u, v in edges)
    print(f"Coloring valid: {valid}")
